Certainly! Below is a complete implementation of a singly linked list in C. This implementation includes functions to create a new list, insert nodes at the beginning and end, delete nodes, search for a node, and print the list.

```c
#include <stdio.h>
#include <stdlib.h>

// Define the structure for a node in the linked list
struct Node {
    int data;
    struct Node* next;
};

// Function to create a new node
struct Node* createNode(int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a node at the beginning of the list
void insertAtBeginning(struct Node** head, int data) {
    struct Node* newNode = createNode(data);
    newNode->next = *head;
    *head = newNode;
}

// Function to insert a node at the end of the list
void insertAtEnd(struct Node** head, int data) {
    struct Node* newNode = createNode(data);
    if (*head == NULL) {
        *head = newNode;
        return;
    }
    struct Node* temp = *head;
    while (temp->next != NULL) {
        temp = temp->next;
    }
    temp->next = newNode;
}

// Function to delete a node with a specific value
void deleteNode(struct Node** head, int data) {
    struct Node* temp = *head;
    struct Node* prev = NULL;

    // If the node to be deleted is the head node
    if (temp != NULL && temp->data == data) {
        *head = temp->next;
        free(temp);
        return;
    }

    // Search for the node to be deleted
    while (temp != NULL && temp->data != data) {
        prev = temp;
        temp = temp->next;
    }

    // If the node was not found
    if (temp == NULL) {
        printf("Node with data %d not found\n", data);
        return;
    }

    // Unlink the node from the linked list
    prev->next = temp->next;
    free(temp);
}

// Function to search for a node with a specific value
struct Node* searchNode(struct Node* head, int data) {
    struct Node* temp = head;
    while (temp != NULL) {
        if (temp->data == data) {
            return temp;
        }
        temp = temp->next;
    }
    return NULL;
}

// Function to print the linked list
void printList(struct Node* head) {
    struct Node* temp = head;
    while (temp != NULL) {
        printf("%d -> ", temp->data);
        temp = temp->next;
    }
    printf("NULL\n");
}

// Function to free the entire linked list
void freeList(struct Node** head) {
    struct Node* temp = *head;
    struct Node* nextNode;
    while (temp != NULL) {
        nextNode = temp->next;
        free(temp);
        temp = nextNode;
    }
    *head = NULL;
}

int main() {
    struct Node* head = NULL;

    // Insert nodes at the beginning
    insertAtBeginning(&head, 10);
    insertAtBeginning(&head, 20);
    insertAtBeginning(&head, 30);

    // Print the list
    printf("List after inserting at the beginning:\n");
    printList(head);

    // Insert nodes at the end
    insertAtEnd(&head, 40);
    insertAtEnd(&head, 50);

    // Print the list
    printf("List after inserting at the end:\n");
    printList(head);

    // Delete a node
    deleteNode(&head, 20);

    // Print the list
    printf("List after deleting node with data 20:\n");
    printList(head);

    // Search for a node
    struct Node* foundNode = searchNode(head, 50);
    if (foundNode != NULL) {
        printf("Node with data 50 found\n");
    } else {
        printf("Node with data 50 not found\n");
    }

    // Free the list
    freeList(&head);

    // Print the list after freeing
    printf("List after freeing:\n");
    printList(head);

    return 0;
}
```

### Explanation:
1. **Node Structure**: The `Node` structure contains an integer `data` and a pointer `next` to the next node in the list.

2. **createNode**: Allocates memory for a new node and initializes it with the given data.

3. **insertAtBeginning**: Inserts a new node at the beginning of the list. The `head` pointer is updated to point to the new node.

4. **insertAtEnd**: Inserts a new node at the end of the list. If the list is empty, the new node becomes the head. Otherwise, it traverses to the end and appends the new node.

5. **deleteNode**: Deletes a node with the specified data. It handles the case where the node to be deleted is the head node separately. If the node is not found, it prints an error message.

6. **searchNode**: Searches for a node with the specified data and returns a pointer to it if found. Otherwise, returns `NULL`.

7. **printList**: Traverses the list and prints each node's data followed by an arrow, ending with `NULL`.

8. **freeList**: Frees all nodes in the list to prevent memory leaks. The `head` pointer is set to `NULL` after freeing.

9. **main**: Demonstrates the usage of the linked list functions by inserting, deleting, searching, and printing nodes.

This implementation provides a basic framework for a singly linked list in C. You can extend it further by adding more functionality, such as inserting at a specific position, reversing the list, or implementing a doubly linked list.
